(5160539, 750508, 96751, '<td valign="top">Love this.  That''s either a very little girl, or a gargantuan cat...  Very moody and perfectly fits the challenge, although the top and bottom borders really feel unnecessary.</td>', 'Love this.  That''s either a very little girl, or a gargantuan cat...  Very moody and perfectly fits the challenge, although the top and bottom borders really feel unnecessary.', '2008-12-31 15:50:32.000000', NULL, 1),
(5160543, 751547, 96751, '<td valign="top">Fabulous abstract.  The lighting, the shape and tone of the butterfly and frame, the fine thread/twig.  Love this.  I hope it does really well, but have notice that abstracts have a hard time here.</td>', 'Fabulous abstract.  The lighting, the shape and tone of the butterfly and frame, the fine thread/twig.  Love this.  I hope it does really well, but have notice that abstracts have a hard time here.', '2008-12-31 15:52:22.000000', NULL, 1),
(5160545, 751576, 96751, '<td valign="top">LOL!  Great idea for "transparency", but the shot is too busy.  The wicker background, the cushion/blanket, all detract from the bubbles and doggie.</td>', 'LOL!  Great idea for "transparency", but the shot is too busy.  The wicker background, the cushion/blanket, all detract from the bubbles and doggie.', '2008-12-31 15:53:12.000000', NULL, 1),
(5160549, 750979, 96751, '<td valign="top">I like the idea, but the execution is a bit wanting for me.  Better lighting on the contents of the glass would have made a huge difference, and perhaps a different shaped glass for the milk wouldn''t have made this feel so top-heavy.</td>', 'I like the idea, but the execution is a bit wanting for me.  Better lighting on the contents of the glass would have made a huge difference, and perhaps a different shaped glass for the milk wouldn''t have made this feel so top-heavy.', '2008-12-31 15:54:27.000000', NULL, 1),
(5160557, 751384, 96751, '<td valign="top">Marvelous crispness, colors, composition.  The splash and "castoffs" are terrific, the bottle mouth stellar.  However... I''m not totally convinced it meets the challenge.  Had we viewed the splash THROUGH the bottle....</td>', 'Marvelous crispness, colors, composition.  The splash and "castoffs" are terrific, the bottle mouth stellar.  However... I''m not totally convinced it meets the challenge.  Had we viewed the splash THROUGH the bottle....', '2008-12-31 15:56:40.000000', NULL, 1),
(5160560, 750397, 96751, '<td valign="top">Wow!  Talk about Twilight Zone!!!  The negative effect makes this kinda creepy, and I kinda like that.  Excellent abstract execution of the challenge.  One of my faves.</td>', 'Wow!  Talk about Twilight Zone!!!  The negative effect makes this kinda creepy, and I kinda like that.  Excellent abstract execution of the challenge.  One of my faves.', '2008-12-31 15:57:38.000000', NULL, 1),
(5160564, 751296, 96751, '<td valign="top">Great shot.  But I love kitties so I may be biased...</td>', 'Great shot.  But I love kitties so I may be biased...', '2008-12-31 15:58:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5160570, 750008, 96751, '<td valign="top">Great idea.  Would have loved a bit more implied depth, with shadows or something.</td>', 'Great idea.  Would have loved a bit more implied depth, with shadows or something.', '2008-12-31 15:59:34.000000', NULL, 1),
(5160576, 750058, 96751, '<td valign="top">What a beautiful shot.  Love the shapes and colors.  The lighting is terrific and really works with the gradient.  The doubly "transparent" content works for me.</td>', 'What a beautiful shot.  Love the shapes and colors.  The lighting is terrific and really works with the gradient.  The doubly "transparent" content works for me.', '2008-12-31 16:01:11.000000', NULL, 1),
(5160584, 750831, 96751, '<td valign="top">How Degas!!!  This is so beautiful. The colors and shapes, the lighting.  But I''m really torn on the crop.  Though it does work with the knob, scrolling down to type my comment cuts off the top of the shot, and I like that as much or even more.</td>', 'How Degas!!!  This is so beautiful. The colors and shapes, the lighting.  But I''m really torn on the crop.  Though it does work with the knob, scrolling down to type my comment cuts off the top of the shot, and I like that as much or even more.', '2008-12-31 16:03:18.000000', NULL, 1),
(5160585, 750111, 96751, '<td valign="top">I''d give higher marks if the guy was in focus instead of the flame.</td>', 'I''d give higher marks if the guy was in focus instead of the flame.', '2008-12-31 16:04:04.000000', NULL, 1),
(5160587, 751526, 96751, '<td valign="top">Awesome.  Front page stuff.  This is a perfect submission for this challenge.</td>', 'Awesome.  Front page stuff.  This is a perfect submission for this challenge.', '2008-12-31 16:04:30.000000', NULL, 1),
(5160594, 750602, 96751, '<td valign="top">Great abstract and colors.</td>', 'Great abstract and colors.', '2008-12-31 16:06:06.000000', NULL, 1),
(5160597, 750937, 96751, '<td valign="top">Great idea.  The composition is a bit off though.  Maybe having the flowers more tightly arranged?</td>', 'Great idea.  The composition is a bit off though.  Maybe having the flowers more tightly arranged?', '2008-12-31 16:07:14.000000', NULL, 1),
(5160604, 751517, 96751, '<td valign="top">This gets my vote for funniest shot.  Really well done. Lighting really highlights his color.  His expression is priceless.  (Do fish have expressions?)  My only little gripe is that the sign is out of focus.</td>', 'This gets my vote for funniest shot.  Really well done. Lighting really highlights his color.  His expression is priceless.  (Do fish have expressions?)  My only little gripe is that the sign is out of focus.', '2008-12-31 16:08:52.000000', NULL, 1),
(5160612, 751609, 96751, '<td valign="top">Nice concept and colors.  Just a bit too busy for my taste.</td>', 'Nice concept and colors.  Just a bit too busy for my taste.', '2008-12-31 16:13:06.000000', NULL, 1),
(5160614, 750128, 96751, '<td valign="top">Nice idea.  I think it''s a little oversaturated and that detracts from the petal details.</td>', 'Nice idea.  I think it''s a little oversaturated and that detracts from the petal details.', '2008-12-31 16:14:25.000000', NULL, 1),
(5160617, 751004, 96751, '<td valign="top">LOL!  Great title.  Nice shot.  Maybe a little less contrast.</td>', 'LOL!  Great title.  Nice shot.  Maybe a little less contrast.', '2008-12-31 16:15:17.000000', NULL, 1),
(5160620, 750664, 96751, '<td valign="top">Wow.  This is so beautiful.  The rough ice makes a great contrast with the smooth surface, and the dots on the fish really complement the empty patches.</td>', 'Wow.  This is so beautiful.  The rough ice makes a great contrast with the smooth surface, and the dots on the fish really complement the empty patches.', '2008-12-31 16:16:15.000000', NULL, 1),
(5160624, 751449, 96751, '<td valign="top">Wonderful.  I love absolutely everything about it: lighting, tones, shapes, subject.  The sharp (no pun intended) detail of the thorns, and the soft focus of the magnifier.  Oh.  Would front page if up to me, but the nontraditional crop my offput some.</td>', 'Wonderful.  I love absolutely everything about it: lighting, tones, shapes, subject.  The sharp (no pun intended) detail of the thorns, and the soft focus of the magnifier.  Oh.  Would front page if up to me, but the nontraditional crop my offput some.', '2008-12-31 16:19:26.000000', NULL, 1),
(5160628, 750490, 96751, '<td valign="top">This is so terrific.  I''m just wondering why the background is so dull, while the image through the sphere is so bright.</td>', 'This is so terrific.  I''m just wondering why the background is so dull, while the image through the sphere is so bright.', '2008-12-31 16:20:02.000000', NULL, 1),
(5160629, 751390, 96751, '<td valign="top">Terrific colors.</td>', 'Terrific colors.', '2008-12-31 16:20:39.000000', NULL, 1),
(5160634, 750835, 96751, '<td valign="top">Amazing shot.  LOVE the underwater distortion of his front hands.  Paws.  Whatevers...</td>', 'Amazing shot.  LOVE the underwater distortion of his front hands.  Paws.  Whatevers...', '2008-12-31 16:21:50.000000', NULL, 1),
(5160637, 751491, 96751, '<td valign="top">Wonderful abstract in my favorite color.  The marble just appears a bit blurred to me.</td>', 'Wonderful abstract in my favorite color.  The marble just appears a bit blurred to me.', '2008-12-31 16:23:42.000000', NULL, 1),
(5160639, 751593, 96751, '<td valign="top">Lots of shots with this type of crop.  Really beautiful subject and execution.</td>', 'Lots of shots with this type of crop.  Really beautiful subject and execution.', '2008-12-31 16:24:22.000000', NULL, 1),
(5160640, 751215, 96751, '<td valign="top">Nice architectural, but the yellow lights are really distracting.</td>', 'Nice architectural, but the yellow lights are really distracting.', '2008-12-31 16:25:04.000000', NULL, 1),
(5160641, 750362, 96751, '<td valign="top">Almost did a shot like this.  Nicely done.  Love the subtle tones.</td>', 'Almost did a shot like this.  Nicely done.  Love the subtle tones.', '2008-12-31 16:25:41.000000', NULL, 1),
(5160642, 750935, 96751, '<td valign="top">Great work with the sphere.</td>', 'Great work with the sphere.', '2008-12-31 16:26:08.000000', NULL, 1),
(5160645, 750830, 96751, '<td valign="top">This is a really strange shot.  Took me a while to figure out he''s holding a pane.  Am not gadget-oriented enough to figure out what the gadget is.  Love his expression.  And yet, this is just a really strange shot!</td>', 'This is a really strange shot.  Took me a while to figure out he''s holding a pane.  Am not gadget-oriented enough to figure out what the gadget is.  Love his expression.  And yet, this is just a really strange shot!', '2008-12-31 16:27:29.000000', NULL, 1),
(5160646, 751330, 96751, '<td valign="top">Awesome street scene.  The color treatment really makes this feel like NY.</td>', 'Awesome street scene.  The color treatment really makes this feel like NY.', '2008-12-31 16:28:06.000000', NULL, 1),
(5160648, 750181, 96751, '<td valign="top">I LOVE this!  What a beautiful idea.  The lighting makes it look like its own little world, and really sets the subject apart from the rest of the shot.</td>', 'I LOVE this!  What a beautiful idea.  The lighting makes it look like its own little world, and really sets the subject apart from the rest of the shot.', '2008-12-31 16:29:38.000000', NULL, 1),
(5160914, 751577, 52130, '<td valign="top">cute, but you could have been a little neater with the edges</td>', 'cute, but you could have been a little neater with the edges', '2008-12-31 18:17:22.000000', NULL, 1),
(5160922, 751079, 52130, '<td valign="top">i really like the set up but I''m not a fan of that  (black) border or the amount of red in her skin</td>', 'i really like the set up but I''m not a fan of that  (black) border or the amount of red in her skin', '2008-12-31 18:21:31.000000', NULL, 1),
(5160923, 751588, 65405, '<td valign="top">This is truly what the challenge meant!  Well done!</td>', 'This is truly what the challenge meant!  Well done!', '2008-12-31 18:21:45.000000', NULL, 1),
(5160925, 750968, 52130, '<td valign="top">haha, very clever and great job in matching the quality of light in reality with that of the painting</td>', 'haha, very clever and great job in matching the quality of light in reality with that of the painting', '2008-12-31 18:23:20.000000', NULL, 1),
(5160928, 750508, 52130, '<td valign="top">oooh, scary, I like it</td>', 'oooh, scary, I like it', '2008-12-31 18:27:23.000000', NULL, 1),
