(5161134, 751577, 96751, '<td valign="top">Wow!  VERY creative. Worthy of the front page.  Just wish you''d have checked for stray hairs before shooting.  Especially the one sticking out of her left eye and from her nose...</td>', 'Wow!  VERY creative. Worthy of the front page.  Just wish you''d have checked for stray hairs before shooting.  Especially the one sticking out of her left eye and from her nose...', '2008-12-31 20:20:21.000000', NULL, 1),
(5161135, 750006, 96751, '<td valign="top">Beautiful.  Excellent low-light capture.</td>', 'Beautiful.  Excellent low-light capture.', '2008-12-31 20:20:45.000000', NULL, 1),
(5161137, 751586, 96751, '<td valign="top">Nice macro!</td>', 'Nice macro!', '2008-12-31 20:21:00.000000', NULL, 1),
(5161145, 751402, 96751, '<td valign="top">Gorgeous abstract.  Interesting shapes and colors</td>', 'Gorgeous abstract.  Interesting shapes and colors', '2008-12-31 20:24:04.000000', NULL, 1),
(5161150, 750637, 96751, '<td valign="top">Wonderful colors.  I love these thermometers!</td>', 'Wonderful colors.  I love these thermometers!', '2008-12-31 20:26:03.000000', NULL, 1),
(5161156, 751588, 96751, '<td valign="top">Wow!  Top 10!  Very Zen.  Love the contrast of the stark black lines and the brilliant white round shapes.  Great dof.</td>', 'Wow!  Top 10!  Very Zen.  Love the contrast of the stark black lines and the brilliant white round shapes.  Great dof.', '2008-12-31 20:27:29.000000', NULL, 1),
(5161159, 750898, 96751, '<td valign="top">Amazing period feeling.  Sepia really works for this.</td>', 'Amazing period feeling.  Sepia really works for this.', '2008-12-31 20:28:36.000000', NULL, 1),
(5161161, 750097, 96751, '<td valign="top">This is an incredibly spooky and magnificent shot.  Love the b/w.  Wonder what the fish were thinking...</td>', 'This is an incredibly spooky and magnificent shot.  Love the b/w.  Wonder what the fish were thinking...', '2008-12-31 20:29:24.000000', NULL, 1),
(5161166, 751438, 96751, '<td valign="top">What a sweet kitty.  What a great idea.  I think this is fantastic snapshot, but the quality of the image isn''t that of the other entries.  Sharper lighting might have helped offset the "blur" of the screen.</td>', 'What a sweet kitty.  What a great idea.  I think this is fantastic snapshot, but the quality of the image isn''t that of the other entries.  Sharper lighting might have helped offset the "blur" of the screen.', '2008-12-31 20:31:31.000000', NULL, 1),
(5161376, 751474, 69504, '<td valign="top">abstract subject</td>', 'abstract subject', '2008-12-31 22:47:58.000000', NULL, 1),
(5161377, 751155, 69504, '<td valign="top">excellent subject, could be a little brighter</td>', 'excellent subject, could be a little brighter', '2008-12-31 22:50:00.000000', NULL, 1),
(5161381, 750344, 69504, '<td valign="top">nice idea but too sharp</td>', 'nice idea but too sharp', '2008-12-31 22:52:31.000000', NULL, 1),
