(5161723, 751508, 50695, '<td valign="top">I''m doubling your score for that wonderful title: 6</td>', 'I''m doubling your score for that wonderful title: 6', '2009-01-01 01:17:08.000000', NULL, 1),
(5161739, 751547, 88580, '<td valign="top">Very nice.  Hell, this one might even get published on 1x.com.  It has a good overlay-like quality to it.</td>', 'Very nice.  Hell, this one might even get published on 1x.com.  It has a good overlay-like quality to it.', '2009-01-01 01:26:53.000000', NULL, 1),
(5161746, 751586, 88580, '<td valign="top">The comp. reaches out and pulls my eyes from top-to-bottom, left-to-right.  There''s nothing particularly interesting at the end of the journey (but I do like it overall), but kudos for directing me through the image.</td>', 'The comp. reaches out and pulls my eyes from top-to-bottom, left-to-right.  There''s nothing particularly interesting at the end of the journey (but I do like it overall), but kudos for directing me through the image.', '2009-01-01 01:30:53.000000', NULL, 1),
(5161753, 750481, 88580, '<td valign="top">I''m afraid you''ll get hammered by the people who interpret the challenge descriptions anally.  This is an excellent take on the theme.  It tells a good story.  As an added bonus, the bright buildings and the dark figure are puzzling.  This probably won''t make it to the front page, but it should.</td>', 'I''m afraid you''ll get hammered by the people who interpret the challenge descriptions anally.  This is an excellent take on the theme.  It tells a good story.  As an added bonus, the bright buildings and the dark figure are puzzling.  This probably won''t make it to the front page, but it should.', '2009-01-01 01:36:22.000000', NULL, 1),
(5161756, 751153, 88580, '<td valign="top">Beautiful abstract.  No further words needed...will just simply admire it.</td>', 'Beautiful abstract.  No further words needed...will just simply admire it.', '2009-01-01 01:38:38.000000', NULL, 1),
(5161757, 751601, 88580, '<td valign="top">Wow...this is the second awesome abstract in a row.  (Checking web-browser''s address bar to make sure I''m in the right place).</td>', 'Wow...this is the second awesome abstract in a row.  (Checking web-browser''s address bar to make sure I''m in the right place).', '2009-01-01 01:41:12.000000', NULL, 1),
(5161766, 750603, 88580, '<td valign="top">I applaud you for putting the transparent stuff in between you &amp; the subject in a different way.  The banding in the sky is a little distracting.</td>', 'I applaud you for putting the transparent stuff in between you & the subject in a different way.  The banding in the sky is a little distracting.', '2009-01-01 01:46:38.000000', NULL, 1),
(5161770, 750409, 88580, '<td valign="top">I don''t think I''ve ever seen an image toned in this shade of peach(?) before.  I dig it.</td>', 'I don''t think I''ve ever seen an image toned in this shade of peach(?) before.  I dig it.', '2009-01-01 01:49:56.000000', NULL, 1),
(5161772, 750194, 88580, '<td valign="top">I don''t feel qualified to comment on something this profound.</td>', 'I don''t feel qualified to comment on something this profound.', '2009-01-01 01:51:29.000000', NULL, 1),
(5161775, 751293, 88580, '<td valign="top">Brilliant; the work of a master.  L.H.O.O.Q. for sure.</td>', 'Brilliant; the work of a master.  L.H.O.O.Q. for sure.', '2009-01-01 01:57:03.000000', NULL, 1),
(5161776, 749941, 88580, '<td valign="top">Guessing this is a real scene with no pictures for backdrops?  This should be on the front page.</td>', 'Guessing this is a real scene with no pictures for backdrops?  This should be on the front page.', '2009-01-01 01:59:44.000000', NULL, 1),
(5161781, 751458, 88580, '<td valign="top">Well, the wine glass theme has been done to death.  The addition of a decanter and the muted tones are nice, though.</td>', 'Well, the wine glass theme has been done to death.  The addition of a decanter and the muted tones are nice, though.', '2009-01-01 02:02:45.000000', NULL, 1),
(5161813, 750097, 37252, '<td valign="top">Great idea though I feel it needs to be rotated 90 degrees counter clockwise. Still deserving of an 8</td>', 'Great idea though I feel it needs to be rotated 90 degrees counter clockwise. Still deserving of an 8', '2009-01-01 02:49:58.000000', NULL, 1),
(5161883, 750606, 50515, '<td valign="top">where''s trancparency????/</td>', 'where''s trancparency????/', '2009-01-01 04:36:13.000000', NULL, 1),
(5162073, 750372, 30982, '<td valign="top">Great use of a soft focus technique to make the picture more about form, light, feel.</td>', 'Great use of a soft focus technique to make the picture more about form, light, feel.', '2009-01-01 08:31:46.000000', NULL, 1),
(5162075, 750831, 30982, '<td valign="top">Lovely shot - something I could see on a card.</td>', 'Lovely shot - something I could see on a card.', '2009-01-01 08:32:38.000000', NULL, 1),
(5162079, 751159, 30982, '<td valign="top">Heh!  The question of children everywhere!  Very clean windshield by the way.</td>', 'Heh!  The question of children everywhere!  Very clean windshield by the way.', '2009-01-01 08:33:59.000000', NULL, 1),
(5162082, 751594, 30982, '<td valign="top">Great look captured and I like that we only see one fish.  Really like the way the color is reflected on the surface.</td>', 'Great look captured and I like that we only see one fish.  Really like the way the color is reflected on the surface.', '2009-01-01 08:35:18.000000', NULL, 1),
(5162084, 751350, 30982, '<td valign="top">No idea what I''m looking at here and really don''t mind that I don''t know.  A story in three parts.</td>', 'No idea what I''m looking at here and really don''t mind that I don''t know.  A story in three parts.', '2009-01-01 08:36:01.000000', NULL, 1),
(5162087, 751215, 30982, '<td valign="top">I like shots like this, and this one is very nicely done.</td>', 'I like shots like this, and this one is very nicely done.', '2009-01-01 08:36:50.000000', NULL, 1),
(5162090, 751600, 30982, '<td valign="top">Very pretty - you''ve also managed to sneak a hint of warmth into a very cold scene with that bokeh.</td>', 'Very pretty - you''ve also managed to sneak a hint of warmth into a very cold scene with that bokeh.', '2009-01-01 08:38:11.000000', NULL, 1),
(5162092, 751474, 30982, '<td valign="top">Very cool abstractish thing - great use of the shapes, colors, refractions.</td>', 'Very cool abstractish thing - great use of the shapes, colors, refractions.', '2009-01-01 08:38:41.000000', NULL, 1),
(5162101, 751426, 30982, '<td valign="top">Very nice way to add texture to a photograph!</td>', 'Very nice way to add texture to a photograph!', '2009-01-01 08:41:41.000000', NULL, 1),
(5162104, 751567, 30982, '<td valign="top">I like this - very nicely done.  Mysterious, and a bit on the dark side..  I''m guessing it''s a glass bowl or plate?  Worked very well for this.</td>', 'I like this - very nicely done.  Mysterious, and a bit on the dark side..  I''m guessing it''s a glass bowl or plate?  Worked very well for this.', '2009-01-01 08:43:03.000000', NULL, 1),
(5162250, 750097, 30982, '<td valign="top">Best of the bunch.  Excellent light, composition, conversion, etc.  Mostly just a great feel to the shot - relaxed, zen-like.  I could see this in a photography magazine.</td>', 'Best of the bunch.  Excellent light, composition, conversion, etc.  Mostly just a great feel to the shot - relaxed, zen-like.  I could see this in a photography magazine.', '2009-01-01 09:44:56.000000', NULL, 1),
