(5164712, 750505, 31456, '<td valign="top">Very nice, but could be a little cleaner.</td>', 'Very nice, but could be a little cleaner.', '2009-01-02 08:11:41.000000', NULL, 1),
(5164716, 750094, 31456, '<td valign="top">I know it may technically be perfectly level, but at first glance, it looks really crooked. Other than that, it''s great.</td>', 'I know it may technically be perfectly level, but at first glance, it looks really crooked. Other than that, it''s great.', '2009-01-02 08:16:51.000000', NULL, 1),
(5164722, 750008, 31456, '<td valign="top">Very clever. I really like it :)</td>', 'Very clever. I really like it :)', '2009-01-02 08:18:49.000000', NULL, 1),
(5164734, 750128, 31456, '<td valign="top">Whoa, it''s growing on the outside! Nice illusion, intended or not.</td>', 'Whoa, it''s growing on the outside! Nice illusion, intended or not.', '2009-01-02 08:29:46.000000', NULL, 1),
(5164735, 750409, 31456, '<td valign="top">I really like this shot, but I think the dark line on the bottom pulls the eye away from the subject. Did you try cropping it out? It would mean cutting down on the sky a bit, too, but over all, I think it''d work better.<br/> <br/>7</td>', 'I really like this shot, but I think the dark line on the bottom pulls the eye away from the subject. Did you try cropping it out? It would mean cutting down on the sky a bit, too, but over all, I think it''d work better. 7', '2009-01-02 08:29:56.000000', NULL, 1),
(5164741, 750980, 31456, '<td valign="top">The photograph isn''t really taken <b>through</b> a transparent object, and though the colors are good, it still looks a bit snapshot-y.</td>', 'The photograph isn''t really taken through a transparent object, and though the colors are good, it still looks a bit snapshot-y.', '2009-01-02 08:33:26.000000', NULL, 1),
(5164769, 751004, 31456, '<td valign="top">Very crisp, and a nice pun. I''m having trouble getting a sense of perspective, though, and that line is bugging me.</td>', 'Very crisp, and a nice pun. I''m having trouble getting a sense of perspective, though, and that line is bugging me.', '2009-01-02 08:56:12.000000', NULL, 1),
