(5165196, 751588, 98022, '<td valign="top">Nice abstract view. Might have been a little stronger if the background to the lower right was not visible. JMHO. Overall a great photo. :)</td>', 'Nice abstract view. Might have been a little stronger if the background to the lower right was not visible. JMHO. Overall a great photo. :)', '2009-01-02 13:17:19.000000', NULL, 1),
