(5166501, 750964, 42495, '<td valign="top">Cool picture, but I see a lot of reflection but not a lot of transparency.</td>', 'Cool picture, but I see a lot of reflection but not a lot of transparency.', '2009-01-03 00:18:03.000000', NULL, 1),
(5166502, 750608, 42495, '<td valign="top">Very nice sunrise or sunset, but I don''t really see the transparency.</td>', 'Very nice sunrise or sunset, but I don''t really see the transparency.', '2009-01-03 00:18:52.000000', NULL, 1),
(5166617, 751536, 83313, '<td valign="top">Kind of interesting, but to be honest, it''s not thrilling me. I think it''s the yellow color of the lights. Out of curiosity, I did some adjustments on this and I think It has some real potential as a b/w image.</td>', 'Kind of interesting, but to be honest, it''s not thrilling me. I think it''s the yellow color of the lights. Out of curiosity, I did some adjustments on this and I think It has some real potential as a b/w image.', '2009-01-03 02:00:23.000000', NULL, 1),
(5166627, 750481, 83313, '<td valign="top">As has certainly been mentioned by others, I want to know how you did this. Very convincing.</td>', 'As has certainly been mentioned by others, I want to know how you did this. Very convincing.', '2009-01-03 02:02:10.000000', NULL, 1),
(5166649, 750603, 83313, '<td valign="top">I''m afraid this just does not work well for me. Focus is clear and colors are decent, but the composition is plain and does not seem to lead my eye anywhere. That water looks partially frozen. Perhaps a lower perspective, if possible, could have caught some interesting play of light off that semi frozen texture. A different time of day, with the sun lower in the sky would also have played well with the ice.</td>', 'I''m afraid this just does not work well for me. Focus is clear and colors are decent, but the composition is plain and does not seem to lead my eye anywhere. That water looks partially frozen. Perhaps a lower perspective, if possible, could have caught some interesting play of light off that semi frozen texture. A different time of day, with the sun lower in the sky would also have played well with the ice.', '2009-01-03 02:07:24.000000', NULL, 1),
(5166655, 751153, 83313, '<td valign="top">Blurry, soft, and a fascinating semi-abstract. I like the play of light through the water and leaves.</td>', 'Blurry, soft, and a fascinating semi-abstract. I like the play of light through the water and leaves.', '2009-01-03 02:09:31.000000', NULL, 1),
(5166661, 750775, 83313, '<td valign="top">I like the effect, but the photo just does not do anything for me. Not totally sure what to suggest.</td>', 'I like the effect, but the photo just does not do anything for me. Not totally sure what to suggest.', '2009-01-03 02:12:07.000000', NULL, 1),
(5166669, 750495, 83313, '<td valign="top">This must be in a zoo or aquarium, but it looks like the boy is underwater.</td>', 'This must be in a zoo or aquarium, but it looks like the boy is underwater.', '2009-01-03 02:13:32.000000', NULL, 1),
(5166681, 750602, 83313, '<td valign="top">Oh, cool, I haven''t seen a Ker-Plunk! game in years.</td>', 'Oh, cool, I haven''t seen a Ker-Plunk! game in years.', '2009-01-03 02:16:12.000000', NULL, 1),
(5166691, 750097, 83313, '<td valign="top">Didn''t I see her in the Asia challenge? I think I like this one a little better, though they are both interesting shots.</td>', 'Didn''t I see her in the Asia challenge? I think I like this one a little better, though they are both interesting shots.', '2009-01-03 02:17:43.000000', NULL, 1),
