(5170076, 751604, 83313, '<td valign="top">Simple, but effective.</td>', 'Simple, but effective.', '2009-01-04 13:24:58.000000', NULL, 1),
(5170080, 751092, 83313, '<td valign="top">Good thing you kept that picture in the background clearly visible as a framed photo, or the DQ police would be after you!</td>', 'Good thing you kept that picture in the background clearly visible as a framed photo, or the DQ police would be after you!', '2009-01-04 13:26:02.000000', NULL, 1),
(5170111, 750964, 83313, '<td valign="top"><strike>I see reflection, not transparency. Am I being too anal about this?</strike> On the other hand, the gator''s eyelids are transparent. Not sure everyone will get that. It took me a bit to realize what the transparent part was. Good luck with this, though I expect you to get killed with DNMC votes.<br/> <br/>As far as the image itself, I think it really has a lot of wonderful potential that can be brought out with some common adjustments. Out of curiosity, I copied this into PaintShop Pro and did some levels, curves, saturation, clarify, contrast and sharpening to it.  It really brought out some wonderful detail in this gator. I saved my result in case you are interested, if not, I will delete it shortly after the challenge.</td>', 'I see reflection, not transparency. Am I being too anal about this? On the other hand, the gator''s eyelids are transparent. Not sure everyone will get that. It took me a bit to realize what the transparent part was. Good luck with this, though I expect you to get killed with DNMC votes. As far as the image itself, I think it really has a lot of wonderful potential that can be brought out with some common adjustments. Out of curiosity, I copied this into PaintShop Pro and did some levels, curves, saturation, clarify, contrast and sharpening to it.  It really brought out some wonderful detail in this gator. I saved my result in case you are interested, if not, I will delete it shortly after the challenge.', '2009-01-04 13:40:15.000000', NULL, 1),
(5170117, 750900, 83313, '<td valign="top">A metal statuette on the sofa? I''m not totally sure what this is. Nothing is in sharp focus. Well, maybe the reflection of the brick wall is.</td>', 'A metal statuette on the sofa? I''m not totally sure what this is. Nothing is in sharp focus. Well, maybe the reflection of the brick wall is.', '2009-01-04 13:41:41.000000', NULL, 1),
(5170127, 751494, 83313, '<td valign="top">The transparent window is not hit-you-in-the-face obvious, but it''s there. I like the softness in this.</td>', 'The transparent window is not hit-you-in-the-face obvious, but it''s there. I like the softness in this.', '2009-01-04 13:43:21.000000', NULL, 1),
(5170251, 750879, 100495, '<td valign="top">I''d love to know how you did this within the rules!</td>', 'I''d love to know how you did this within the rules!', '2009-01-04 14:46:54.000000', NULL, 1),
(5170258, 751494, 100495, '<td valign="top">I''m <b>thinking</b> that the window reflections add an ambiance to this image.  Nicely done.</td>', 'I''m thinking that the window reflections add an ambiance to this image.  Nicely done.', '2009-01-04 14:49:59.000000', NULL, 1),
(5170267, 751577, 100495, '<td valign="top">Clever. Unsettling. Likely to give me nightmares!</td>', 'Clever. Unsettling. Likely to give me nightmares!', '2009-01-04 14:53:24.000000', NULL, 1),
(5170273, 750490, 100495, '<td valign="top">At last, a proper transparency photo!  The inverted hut on the right really sets it off.</td>', 'At last, a proper transparency photo!  The inverted hut on the right really sets it off.', '2009-01-04 14:55:50.000000', NULL, 1),
(5170278, 751602, 100495, '<td valign="top">Beautiful complimentary colours.</td>', 'Beautiful complimentary colours.', '2009-01-04 14:57:00.000000', NULL, 1),
(5170282, 751566, 100495, '<td valign="top">I''m confused about what this is, even with the descriptive title.  Very grainy/noisy.</td>', 'I''m confused about what this is, even with the descriptive title.  Very grainy/noisy.', '2009-01-04 14:58:24.000000', NULL, 1),
(5170287, 750645, 100495, '<td valign="top">Could use more space on the right to get your elbow in.</td>', 'Could use more space on the right to get your elbow in.', '2009-01-04 15:00:34.000000', NULL, 1),
(5170289, 750097, 100495, '<td valign="top">This is excellent. Well done to your very brave model.</td>', 'This is excellent. Well done to your very brave model.', '2009-01-04 15:01:24.000000', NULL, 1),
