(5174095, 751384, 39850, '<td valign="top">8 - Very nice, like your tones.  Wish it had a little more compositional balance.</td>', '8 - Very nice, like your tones.  Wish it had a little more compositional balance.', '2009-01-06 00:52:06.000000', NULL, 1),
(5174100, 749941, 76430, '<td valign="top">LOL, I hope that isn''t a picture taken earlier in the background.  Since the <a href="//www.dpchallenge.com/image.php?IMAGE_ID=742750" rel="nofollow" target="_blank">background is identical </a> I''ll go out on a limb and guess it''s <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=86447" rel="nofollow" target="_blank">LydiaToo</a>.  You did a better job on the transparent glass in the original. <br/>(edit to fix URL and remove last sentence; same score)</td>', 'LOL, I hope that isn''t a picture taken earlier in the background.  Since the background is identical  I''ll go out on a limb and guess it''s  LydiaToo.  You did a better job on the transparent glass in the original. (edit to fix URL and remove last sentence; same score)', '2009-01-06 00:57:27.000000', NULL, 1),
