(5178403, 751384, 60495, '<td valign="top">Nicely done as always, congratulations!</td>', 'Nicely done as always, congratulations!', '2009-01-07 16:27:52.000000', NULL, 0),
(5178436, 751384, 36988, '<td valign="top">A very worthy Blue ribbon winner and a fine addition to your collection of wonderful images. It is a real thrill to watch the artistic progression of someone so talented. You make me want to do better. As a side note... I believe you met the challenge just fine. You possess a great deal of class... far more than some... and I know that you realize that for as many slingers of mud there are, the amount of admirers is tenfold. All the best.</td>', 'A very worthy Blue ribbon winner and a fine addition to your collection of wonderful images. It is a real thrill to watch the artistic progression of someone so talented. You make me want to do better. As a side note... I believe you met the challenge just fine. You possess a great deal of class... far more than some... and I know that you realize that for as many slingers of mud there are, the amount of admirers is tenfold. All the best.', '2009-01-07 16:45:06.000000', NULL, 0),
