INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5178684, 750097, 24454, '<td valign="top">Claire, this is GREAT!  I love your outtakes too, but this is just FABULOUS for Transparency, and your''e right:  Tiffany looks so at peace.  It''s surreal.<br/> <br/>Yes. . .you are certainly not short in the talent department :)   CONGRATULATIONS!</td>', 'Claire, this is GREAT!  I love your outtakes too, but this is just FABULOUS for Transparency, and your''e right:  Tiffany looks so at peace.  It''s surreal. Yes. . .you are certainly not short in the talent department :)   CONGRATULATIONS!', '2009-01-07 18:49:38.000000', NULL, 0),
(5178685, 751458, 24454, '<td valign="top">It''s so funny that you are sharing the podium, led only by Irene because I thought this WAS Irene''s when I saw it in the challenge.   Well, you KNOW what a compliment THAT is!   And this photo is definitely worthy to be in her league :)   CONGRATULATIONS on your first Red Ribbon to complete the set :)<br/> <br/></td>', 'It''s so funny that you are sharing the podium, led only by Irene because I thought this WAS Irene''s when I saw it in the challenge.   Well, you KNOW what a compliment THAT is!   And this photo is definitely worthy to be in her league :)   CONGRATULATIONS on your first Red Ribbon to complete the set :) ', '2009-01-07 18:51:23.000000', NULL, 0),
(5178713, 750879, 28742, '<td valign="top">It was clearly the ghastly horror of this concept that scared voters too much to rate it highly. Evokes WAY too much negative emotion. My ifrst impression was "Oh... my... God. What if that happened to me??" *shudder*</td>', 'It was clearly the ghastly horror of this concept that scared voters too much to rate it highly. Evokes WAY too much negative emotion. My ifrst impression was "Oh... my... God. What if that happened to me??" *shudder*', '2009-01-07 19:32:11.000000', NULL, 0),
(5178717, 751577, 28742, '<td valign="top">Concept is great, execution a little lacking - if you could''ve blended the edges better. But yeah, Basic editing. Whatcanyado. :)</td>', 'Concept is great, execution a little lacking - if you could''ve blended the edges better. But yeah, Basic editing. Whatcanyado. :)', '2009-01-07 19:33:34.000000', NULL, 0),
(5178740, 751462, 68504, '<td valign="top">Visually and thematically most interesting.</td>', 'Visually and thematically most interesting.', '2009-01-07 19:41:30.000000', NULL, 0),
(5178799, 751547, 11769, '<td valign="top">Wonderful work.</td>', 'Wonderful work.', '2009-01-07 19:56:47.000000', NULL, 0),
(5178875, 751365, 13390, '<td valign="top">An interesting and bold move in the challenge. I find this shot interesting to look at, it''s just fun looking at what''s inside and then another level with the reflection. It''s like a 2 fer 1 kinda deal. Nicely done!</td>', 'An interesting and bold move in the challenge. I find this shot interesting to look at, it''s just fun looking at what''s inside and then another level with the reflection. It''s like a 2 fer 1 kinda deal. Nicely done!', '2009-01-07 20:17:14.000000', NULL, 0),
(5178898, 750989, 13390, '<td valign="top">The lensbaby effect is pretty cool, especially for 60mph! Almost got the brown there Bear ;)</td>', 'The lensbaby effect is pretty cool, especially for 60mph! Almost got the brown there Bear ;)', '2009-01-07 20:19:25.000000', NULL, 0),
(5178905, 751606, 13390, '<td valign="top">Your images are always very interesting to me. Most people seem to skip right past them at first glance because they don''t follow the whole mainstream. I like to look at shots like this of your because they make you sit and look at it and just think. Well done!</td>', 'Your images are always very interesting to me. Most people seem to skip right past them at first glance because they don''t follow the whole mainstream. I like to look at shots like this of your because they make you sit and look at it and just think. Well done!', '2009-01-07 20:20:45.000000', NULL, 0),
(5178909, 751583, 13390, '<td valign="top">Now this is just cool! This is a fun shot to look at. I enjoy the colors, composition, and all the cool little hidden elements. I wish this would have done better, but I''m guessing people didn''t take the time to notice it. I like it because you find cool things when you do take the time to look.</td>', 'Now this is just cool! This is a fun shot to look at. I enjoy the colors, composition, and all the cool little hidden elements. I wish this would have done better, but I''m guessing people didn''t take the time to notice it. I like it because you find cool things when you do take the time to look.', '2009-01-07 20:23:02.000000', NULL, 0),
(5178926, 751410, 13390, '<td valign="top">There are some really cool elements to this shot. I really like the frosty look and the efect the have on the lights. At first glance I didn''t notice the woman, but that is a cool element of the shot because you have to keep looking at it to find cool stuff like that.</td>', 'There are some really cool elements to this shot. I really like the frosty look and the efect the have on the lights. At first glance I didn''t notice the woman, but that is a cool element of the shot because you have to keep looking at it to find cool stuff like that.', '2009-01-07 20:29:04.000000', NULL, 0),
(5178931, 750397, 13390, '<td valign="top">I like the effect you achieved here with the b/w conversion. I''m really liking the abstract feel of the shot. Captured very nicely.</td>', 'I like the effect you achieved here with the b/w conversion. I''m really liking the abstract feel of the shot. Captured very nicely.', '2009-01-07 20:30:46.000000', NULL, 0),
(5178937, 750637, 13390, '<td valign="top">I really like the colors here, nice, bright and vibrant. I think it got hit the way it did because of the softness due from the grain, possibly from a crop, so it wasn''t as sharp as it could have been, but hey, I think it adds a cool little effect that I personally think adds to the feel. Good work.</td>', 'I really like the colors here, nice, bright and vibrant. I think it got hit the way it did because of the softness due from the grain, possibly from a crop, so it wasn''t as sharp as it could have been, but hey, I think it adds a cool little effect that I personally think adds to the feel. Good work.', '2009-01-07 20:33:08.000000', NULL, 0),
(5178940, 751153, 13390, '<td valign="top">I think this should have done better. I love the blend of the colors. It has a painty sort of feel that makes it feel relaxing. Good job on this because it caused emotion to someone.</td>', 'I think this should have done better. I love the blend of the colors. It has a painty sort of feel that makes it feel relaxing. Good job on this because it caused emotion to someone.', '2009-01-07 20:34:32.000000', NULL, 0),
